<?php require_once '../config/helpers.php';require_admin();$total=(int)$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Pending'")->fetchColumn();$customers=(int)$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn();$confirmed=(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Confirmed'")->fetchColumn();$recent=$pdo->query('SELECT b.*,c.full_name,c.phone,s.name service_name FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN services s ON s.id=b.service_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>Admin Dashboard</title></head><body><div class="admin-layout"><?php include '_nav.php'; ?><section class="admin-main"><div class="eyebrow">Management console</div><h1>Dashboard Overview</h1><p class="muted">Welcome, <?= e($_SESSION['admin_name']) ?>. Here is your business summary.</p><div class="stats"><div class="stat">Total bookings<strong><?= $total ?></strong></div><div class="stat">Pending requests<strong><?= $pending ?></strong></div><div class="stat">Customers<strong><?= $customers ?></strong></div><div class="stat">Confirmed bookings<strong><?= $confirmed ?></strong></div></div><div class="panel"><h2>Recent Bookings</h2><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Service</th><th>Date & time</th><th>Event place</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $b): ?><tr><td><?= e($b['full_name']) ?></td><td><a href="tel:<?= e($b['phone']) ?>"><?= e($b['phone']) ?></a></td><td><?= e($b['service_name']) ?></td><td><?= e($b['event_date']) ?><br><?= e(date('h:i A',strtotime($b['event_time']))) ?></td><td><?= e($b['event_location']) ?><br><span class="muted small"><?= e($b['full_address']) ?></span></td><td><span class="badge <?= e($b['status']) ?>"><?= e($b['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="6">No bookings received yet.</td></tr><?php endif; ?></tbody></table></div><p><a class="btn" href="bookings.php">Manage all bookings</a></p></div></section></div></body></html>
